uint64_t fn_16(const uint8_t *in, size_t len, uint64_t seed) {
  uint32_t h = seed & 0xffffffff;
  uint32_t h2 = seed >> 32;
  size_t i;

  for (i = 0; i < len; i++) {
    h = (h << 7) | (h >> 25);
    h += (uint32_t)in[i] * 167 + (uint32_t)i;
    h2 = (h2 << 7) | (h2 >> 25);
    h2 += (uint32_t)in[i] * 169 + (uint32_t)i;
  }

  h ^= h2;
  h2 = (h2 ^ (h2 >> 15)) * 11400714785074694087ULL;
  h = (h ^ (h >> 13)) * 6364136223846793005ULL;
  h = (h ^ (h >> 16));
  return h + h2;
}
